#!/usr/bin/env node
/**
 * Regenerate src/lib/supabase/database.generated.ts from the real database.
 *
 *   npm run db:types            uses the stack started by `supabase start` (--local)
 *   DB_URL=postgres://… npm run db:types   uses any reachable Postgres
 *   npm run db:types:check      fails if the committed file differs (schema drift)
 *
 * Safety: the CLI prints errors to stdout, so a plain `> file` redirect would
 * overwrite the types with an error message. This script validates the output
 * and writes only on success. It touches nothing but the generated file;
 * privilege-aware narrowing lives in database.types.ts and is never generated.
 */
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';

const TARGET = 'src/lib/supabase/database.generated.ts';
const HEADER = '// GENERATED by `npm run db:types` (supabase gen types). Do not edit by hand.\n// Privilege-aware types: see database.types.ts.\n';
const check = process.argv.includes('--check');

const args = ['supabase', 'gen', 'types', 'typescript', '--schema', 'public'];
if (process.env.DB_URL) args.push('--db-url', process.env.DB_URL);
else args.push('--local');

let out;
try {
  out = execFileSync('npx', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
} catch (e) {
  console.error(`Type generation failed; ${TARGET} was not modified.\n${(e.stdout || '') + (e.stderr || '')}`.trim());
  process.exit(1);
}
out = out.replace(/^\s+/, '');
if (!out.startsWith('export type Json') || !out.includes('export type Database')) {
  console.error(`Unexpected generator output; ${TARGET} was not modified:\n${out.slice(0, 400)}`);
  process.exit(1);
}
const content = HEADER + out.replace(/\s+$/, '') + '\n';

if (check) {
  const current = existsSync(TARGET) ? readFileSync(TARGET, 'utf8') : '';
  if (current !== content) {
    console.error(`${TARGET} is out of date with the database schema. Run \`npm run db:types\` and review the diff.`);
    process.exit(1);
  }
  console.log(`${TARGET} matches the database schema.`);
} else {
  writeFileSync(TARGET, content);
  console.log(`Wrote ${TARGET}.`);
}
